SELECT s.* FROM SUBSCRIPTION s WHERE s.status = 10 AND s.payment_day IN
#{day}
AND NOT EXISTS ( SELECT 1 FROM PAYMENT p WHERE p.subscription_id = s.subscription_id AND CAST(p.paid_at AS CHAR) LIKE CONCAT(DATE_FORMAT(NOW(), '%Y%m'), '%') )

